const chineseTypes={'States':'邦','Länder':'邦','Government District':'行政大區','Independent City or District':'獨立市／縣','Province':'省','Provinces':'省','County':'縣','Counties':'縣','State':'州','Federal Subjects':'聯邦主體','Administrative region':'行政區','Counties / Cities':'縣／市'};
function tr(raw){
  if(typeof raw!=='string')return raw;const s=raw.trim();
  let zh=Object.keys(translations).find(k=>translations[k]===s)||s;
  if(language==='zh-Hant'){
    if(chineseTypes[s])return chineseTypes[s];
    const exact=Object.keys(translations).find(k=>translations[k]===s);if(exact)return exact;
    if(/^World · \d+ editable regions$/.test(s))return s.replace(/^World · (\d+) editable regions$/,'世界 · $1 個可編輯區域');
    if(/^Color #[a-f0-9]{6}$/i.test(s))return s.replace('Color ','色彩 ');
    if(/^Choose color /.test(s))return s.replace('Choose color ','選擇色彩 ');
    if(/^Use [★●⚑♥✈◆]$/.test(s))return s.replace('Use ','使用 ');
    return chineseTypes[s]||s;
  }
  if(translations[zh])return translations[zh];
  const rules=[[/^世界 · (\d+) 個可編輯區域$/,'World · $1 editable regions'],[/^色彩 (#[a-f0-9]{6})$/i,'Color $1'],[/^選擇色彩 (.*)$/,'Choose color $1'],[/^使用 (.*)$/,'Use $1'],[/^未標記範圍已合併，保留 (\d+) 個已標記區域。$/,'Unmarked areas merged; $1 marked regions preserved.'],[/^正在載入 (.+) 的下一層行政區…$/,'Loading subdivisions of $1…'],[/^已拆分為 (\d+) 個(.+)，可分別上色。$/,'Split into $1 $2 regions. Each can be painted independently.'],[/^載入失敗：(.+)。可再次雙擊重試。$/,'Loading failed: $1. Double-click to retry.'],[/^還原未完成：(.+)。原有編輯已保留。$/,'Restore incomplete: $1. Existing edits preserved.'],[/^無法匯入：(.+)$/,'Import failed: $1'],[/^無法載入地圖：(.+)。請重新整理。$/,'Map failed to load: $1. Please refresh.'],[/^修改 (.+) 的說明$/,'Edit description of $1'],[/^刪除 (.+) 並清除地圖標記$/,'Delete $1 and clear matching map markings']];
  for(const [regex,replacement] of rules)if(regex.test(zh))return zh.replace(regex,replacement);return s;
}
const taiwanNames={'Hsinchu County':'新竹縣','Miaoli County':'苗栗縣','Matsu Islands':'連江縣（馬祖）','Kinmen':'金門縣','Chiayi County':'嘉義縣','Yilan County':'宜蘭縣','Nantou County':'南投縣','Changhua County':'彰化縣','Pingtung County':'屏東縣','Taitung County':'臺東縣','Hualien County':'花蓮縣','Penghu':'澎湖縣','Yunlin County':'雲林縣','Chiayi':'嘉義市','Hsinchu':'新竹市','Keelung':'基隆市','Taichung':'臺中市','Taoyuan':'桃園市','New Taipei':'新北市','Tainan':'臺南市','Taipei':'臺北市','Kaohsiung':'高雄市'};
function regionName(n){if(n.level===0){const raw=n.feature.properties['ISO3166-1-Alpha-2'];const code=/^[A-Z]{2}$/.test(raw||'')?raw:({FRA:'FR',NOR:'NO'})[n.iso];if(/^[A-Z]{2}$/.test(code)){try{return new Intl.DisplayNames([language],{type:'region'}).of(code)}catch{}}}return language==='zh-Hant'&&n.iso==='TWN'?(taiwanNames[n.name]||n.name):n.name}
function translateDOM(root=document.body){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
  while(node=walker.nextNode()){
    if(node.parentElement?.closest('svg,script,style,[data-user-text],select,#region b,.leaflet-tooltip'))continue;
    const old=node.nodeValue,next=tr(old);if(old.trim()&&old.trim()!==next)node.nodeValue=old.replace(old.trim(),next);
  }
  for(const el of root.querySelectorAll?.('[placeholder],[title],[aria-label]')||[]){if(el.closest('svg,[data-user-text]'))continue;for(const a of ['placeholder','title','aria-label']){const v=el.getAttribute(a);if(v&&tr(v)!==v)el.setAttribute(a,tr(v))}}
}
let rawStatus='正在載入世界地圖…';const statusOriginal=status;status=function(message,sticky){rawStatus=message;statusOriginal(tr(message),sticky)};
const promptOriginal=window.prompt.bind(window),confirmOriginal=window.confirm.bind(window);window.prompt=(message,value)=>promptOriginal(tr(message),value);window.confirm=message=>confirmOriginal(tr(message));
const selectOriginalLanguage=select;select=function(n){selectOriginalLanguage(n);$('#region b').textContent=regionName(n);$('#region small').textContent=n.residual?tr('上一層剩餘範圍 · 已標記區域維持獨立'):n.level===0?tr('雙擊拆分；單擊套用標記'):`${tr(n.canonical||'行政區')} · ${n.year||''}`;translateDOM($('#region'))};
const observer=new MutationObserver(records=>{for(const r of records){if(r.type==='characterData'&&r.target.parentElement)translateDOM(r.target.parentElement);else for(const n of r.addedNodes)if(n.nodeType===1)translateDOM(n);else if(n.parentElement)translateDOM(n.parentElement)}});
observer.observe(document.body,{subtree:true,childList:true,characterData:true});
